    H=len(I);W=len(I[0]);seen=set(start);q=deque([(start,[start])])
    while q:
        cell,path=q.popleft()
        if cell in goal: return [p for p in path if p not in start and p not in goal]
        a,b=cell
        for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
            n=(a+da,b+db)
            if 0<=n[0]<H and 0<=n[1]<W and I[n[0]][n[1]]==bg and n not in seen:
                seen.add(n); q.append((n,path+[n]))
    return None
