        a,b=end
        if orient=='h':
            dirs={'L':(0,-1),'R':(0,1),'U':(-1,0),'D':(1,0)}
            ext={'L':(a,b-1),'R':(a,b+1)}
        else:
            dirs={'U':(-1,0),'D':(1,0),'L':(0,-1),'R':(0,1)}
            ext={'U':(a-1,b),'D':(a+1,b)}
        for dn,d in dirs.items():
            starts.append((end,dn,ext[dn],d))
    def free(a,b):
        return 0<=a<H and 0<=b<W and I[a][b]==bg
    def adjgoal(a,b):
