            pass
    # simpler: manual policy enumeration over (initial_dir_name, turn_policy_index)
    dirnames=['L','R','U','D']
    turn_policies={
      0: lambda cur,ax: None,  # none
      1: lambda cur,ax: ax,   # reverse
      2: lambda cur,ax: ('U' if cur[0]>=0 else 'D'),
    }
    best=None
    for pid,tpr in turn_policies.items():
        for ind,(end,dn,ext_dn,aXd) in enumerate(starts):
