                # gather unobstructed rays: move in direction dd until next cell blocked; record max steps
                rays=[]
                for nd,nm in [( (0,-1),'L'),((0,1),'R'),((-1,0),'U'),((1,0),'D')]:
                    n=cur[0]+nd[0]; m=cur[1]+nd[1]
