                    while free(n+k*nd[0],m+k*nd[1]): k+=1
                    rays.append((k,nd,nm))
                if not rays: ok=False; break
                # choose: prefer continuing current dir if available, else policy-based
                cand=[r for r in rays if r[1]==(d[0],d[1])]
                if cand and (pid==0 or True):
                    k,nd,_=max(cand,key=lambda r:r[0])
                    if k>=1:
                        cur=(cur[0]+nd[0],cur[1]+nd[1]); d=nd; path.append(cur); continue
                # fallback: longest ray
                k,nd,_=max(rays,key=lambda r:r[0])
                if k<1: ok=False; break
                cur=(cur[0]+nd[0],cur[1]+nd[1]); d=nd; path.append(cur)
            if not ok: continue
            # verify final: path cells should be bg in input and result should match expected paint
            exp=set((i,j) for i in range(H) for j in range(W) if I[i][j]!=G[i][j] if False else set())
            # just record
