from collections import Counter,deque
def free(I,H,W,a,b):
    return 0<=a<H and 0<=b<W and I[a][b]==Counter(c for r in I for c in r).most_common(1)[0][0]
def adjgoal(cur,Gset):
    return any((cur[0]+da,cur[1]+db) in Gset for da,db in ((1,0),(-1,0),(0,1),(0,-1)))
def simulate(I):
    H=len(I);W=len(I[0])
    bg=Counter(c for r in I for c in r).most_common(1)[0][0]
    S=[(i,j) for i in range(H) for j in range(W) if I[i][j]==3]
    Gc=[(i,j) for i in range(H) for j in range(W) if I[i][j]==2]
    gset=set(Gc); sset=set(S)
    rs={i for i,j in S}; cs={j for i,j in S}
    if len(rs)==1: orient='h'
    else: orient='v'
    ends=[]
    if len(rs)==1:
        row=S[0][0]; ends=[(row,S[0][1]),(row,S[-1][1])]
        dirs={'L':(0,-1),'R':(0,1)}
    else:
        col=S[0][1]; ends=[(S[0][0],col),(S[-1][0],col)]
        dirs={'U':(-1,0),'D':(1,0)}
    exp=set((i,j) for i in range(H) for j in range(W) if I[i][j]!=G[i][j] if False else set())
    matches=[]
    for end,dn in ends,list(dirs.items()):
        cur=end[1]; d=dn
        path=[cur]; ok=True
        while True:
            if adjgoal(cur,gset): break
            rays=[]
            for nd,nm in dirs.items():
                k=0
                while free(I,H,W,cur[0]+k*nd[0],cur[1]+k*nd[1]): k+=1
                if k>=1: rays.append((k,nd,nm))
            if not rays: ok=False; break
            cand=[r for r in rays if r[1]==d]
            if cand:
                k,nd,_=max(cand,key=lambda r:r[0]); d=nd
            else:
                k,nd,_=max(rays,key=lambda r:r[0]); d=nd
            if k<1: ok=False; break
            cur=(cur[0]+nd[0],cur[1]+nd[1]); path.append(cur)
        if ok:
            ps=set(path)
            # painted = path cells minus original bar cells? expected painted should equal ps excluding S
            ep=set((i,j) for i in range(H) for j in range(W) if I[i][j]!=O[i][j] if False else set())
            print(f"demo{n} {orient} start{end[:2]} dir{dn}: {'MATCH' if ps-ends==ep else 'not match'}")

